// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatIllegalArgumentException;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class LmdbReferenceNodeLocatorTest {

	private static final long[] NO_TYPES = { 0, 0, 0, 0 };

	private final LmdbAdjacencyArena arena = new LmdbAdjacencyArena(1 << 20);

	@AfterEach
	void close() {
		arena.close();
	}

	private static long[][] emptyPlanes() {
		return new long[][] { {}, {}, {}, {} };
	}

	@Test
	void predicateWidthUsesCountThresholds() {
		assertThat(LmdbReferenceNodeLocator.predicateWidthForCount(0)).isEqualTo(1);
		assertThat(LmdbReferenceNodeLocator.predicateWidthForCount(100)).isEqualTo(1);
		assertThat(LmdbReferenceNodeLocator.predicateWidthForCount(255)).isEqualTo(1);
		assertThat(LmdbReferenceNodeLocator.predicateWidthForCount(256)).isEqualTo(2);
		assertThat(LmdbReferenceNodeLocator.predicateWidthForCount(65_535)).isEqualTo(2);
		assertThat(LmdbReferenceNodeLocator.predicateWidthForCount(65_536)).isEqualTo(4);
		assertThat(LmdbReferenceNodeLocator.predicateWidthForCount(0xFFFF_FFFFL)).isEqualTo(4);
		assertThatIllegalArgumentException()
				.isThrownBy(() -> LmdbReferenceNodeLocator.predicateWidthForCount(0x1_0000_0000L));
	}

	@Test
	void bitmapRankResolvesBoundarySlots() {
		long[] tops = { 2 * LmdbReferenceNodeLocator.PAGE_SLOTS, 0, 0, 0 };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);
		// slots 0, 63, 64, 4095 on page 0 of the URI type
		long[] payloads = { 0, 63, 64, 4095 };
		for (long payload : payloads) {
			long[][] ordinals = emptyPlanes();
			long[][] refs = emptyPlanes();
			ordinals[LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT] = new long[] { 7 };
			refs[LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT] = new long[] { 1000 + payload };
			builder.addNode(ValueIds.T_URI, payload, ordinals, refs);
		}
		LmdbReferenceNodeLocator locator = builder.build();

		for (long payload : payloads) {
			long headerRef = locator.headerRef(ValueIds.T_URI, payload);
			assertThat(headerRef).as("payload %d", payload).isPositive();
			assertThat(locator.findGroupRun(headerRef, LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT, 7))
					.isEqualTo(1000 + payload);
		}
		// unoccupied slots on the same page are missing nodes
		assertThat(locator.headerRef(ValueIds.T_URI, 1)).isZero();
		assertThat(locator.headerRef(ValueIds.T_URI, 62)).isZero();
		assertThat(locator.headerRef(ValueIds.T_URI, 65)).isZero();
		// an allocated-but-empty page is absent
		assertThat(locator.headerRef(ValueIds.T_URI, LmdbReferenceNodeLocator.PAGE_SLOTS + 1)).isZero();
	}

	@Test
	void fullPageResolvesEveryNode() {
		long[] tops = { LmdbReferenceNodeLocator.PAGE_SLOTS, 0, 0, 0 };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);
		for (long payload = 0; payload < LmdbReferenceNodeLocator.PAGE_SLOTS; payload++) {
			long[][] ordinals = emptyPlanes();
			long[][] refs = emptyPlanes();
			ordinals[LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT] = new long[] { 1 };
			refs[LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT] = new long[] { payload + 1 };
			builder.addNode(ValueIds.T_URI, payload, ordinals, refs);
		}
		LmdbReferenceNodeLocator locator = builder.build();

		for (long payload = 0; payload < LmdbReferenceNodeLocator.PAGE_SLOTS; payload += 97) {
			long headerRef = locator.headerRef(ValueIds.T_URI, payload);
			assertThat(locator.findGroupRun(headerRef, LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT, 1))
					.isEqualTo(payload + 1);
		}
	}

	@Test
	void sparsePagesAcrossTypesResolveIndependently() {
		long[] tops = { 3 * LmdbReferenceNodeLocator.PAGE_SLOTS, LmdbReferenceNodeLocator.PAGE_SLOTS,
				LmdbReferenceNodeLocator.PAGE_SLOTS, LmdbReferenceNodeLocator.PAGE_SLOTS };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);

		long[][] uriOrdinals = emptyPlanes();
		long[][] uriRefs = emptyPlanes();
		uriOrdinals[0] = new long[] { 3 };
		uriRefs[0] = new long[] { 111 };
		builder.addNode(ValueIds.T_URI, 2 * LmdbReferenceNodeLocator.PAGE_SLOTS + 17, uriOrdinals, uriRefs);

		long[][] bnodeOrdinals = emptyPlanes();
		long[][] bnodeRefs = emptyPlanes();
		bnodeOrdinals[3] = new long[] { 9 };
		bnodeRefs[3] = new long[] { 222 };
		builder.addNode(ValueIds.T_BNODE, 17, bnodeOrdinals, bnodeRefs);

		LmdbReferenceNodeLocator locator = builder.build();

		long uriHeader = locator.headerRef(ValueIds.T_URI, 2 * LmdbReferenceNodeLocator.PAGE_SLOTS + 17);
		assertThat(locator.findGroupRun(uriHeader, 0, 3)).isEqualTo(111);
		// the same payload under a different type is a different node
		assertThat(locator.headerRef(ValueIds.T_LITERAL, 17)).isZero();
		long bnodeHeader = locator.headerRef(ValueIds.T_BNODE, 17);
		assertThat(locator.findGroupRun(bnodeHeader, 3, 9)).isEqualTo(222);
		// page 0 and 1 of URI never got nodes
		assertThat(locator.headerRef(ValueIds.T_URI, 17)).isZero();
	}

	@Test
	void allFourPlanesResolveSeparatelyWithHundredPredicates() {
		long[] tops = { LmdbReferenceNodeLocator.PAGE_SLOTS, 0, 0, 0 };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);
		long[][] ordinals = new long[4][];
		long[][] refs = new long[4][];
		for (int plane = 0; plane < 4; plane++) {
			ordinals[plane] = new long[100];
			refs[plane] = new long[100];
			for (int p = 0; p < 100; p++) {
				ordinals[plane][p] = p;
				refs[plane][p] = (plane + 1) * 1000L + p;
			}
		}
		builder.addNode(ValueIds.T_URI, 5, ordinals, refs);
		LmdbReferenceNodeLocator locator = builder.build();

		long headerRef = locator.headerRef(ValueIds.T_URI, 5);
		for (int plane = 0; plane < 4; plane++) {
			assertThat(locator.planeGroupCount(headerRef, plane)).isEqualTo(100);
			for (int p = 0; p < 100; p += 13) {
				assertThat(locator.findGroupRun(headerRef, plane, p)).isEqualTo((plane + 1) * 1000L + p);
			}
			// missing group within an existing node
			assertThat(locator.findGroupRun(headerRef, plane, 100)).isEqualTo(-1);
		}

		long[] entry = new long[2];
		locator.planeEntry(headerRef, 2, 42, entry);
		assertThat(entry[0]).isEqualTo(42);
		assertThat(entry[1]).isEqualTo(3000L + 42);
	}

	@Test
	void twoBytePredicateWidthStoresLargeOrdinals() {
		long[] tops = { LmdbReferenceNodeLocator.PAGE_SLOTS, 0, 0, 0 };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 2, tops);
		long[][] ordinals = emptyPlanes();
		long[][] refs = emptyPlanes();
		ordinals[0] = new long[] { 255, 256, 65_534 };
		refs[0] = new long[] { 1, 2, 3 };
		builder.addNode(ValueIds.T_URI, 0, ordinals, refs);
		LmdbReferenceNodeLocator locator = builder.build();

		long headerRef = locator.headerRef(ValueIds.T_URI, 0);
		assertThat(locator.findGroupRun(headerRef, 0, 255)).isEqualTo(1);
		assertThat(locator.findGroupRun(headerRef, 0, 256)).isEqualTo(2);
		assertThat(locator.findGroupRun(headerRef, 0, 65_534)).isEqualTo(3);
		assertThat(locator.findGroupRun(headerRef, 0, 65_535)).isEqualTo(-1);
	}

	@Test
	void payloadBeyondTheBaseBoundIsOrdinaryAbsence() {
		long[] tops = { LmdbReferenceNodeLocator.PAGE_SLOTS, 0, 0, 0 };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);
		long[][] ordinals = emptyPlanes();
		long[][] refs = emptyPlanes();
		ordinals[0] = new long[] { 1 };
		refs[0] = new long[] { 55 };
		builder.addNode(ValueIds.T_URI, 3, ordinals, refs);
		LmdbReferenceNodeLocator locator = builder.build();

		// beyond the top-array bound: base absence without touching native memory (I18-safe by construction)
		assertThat(locator.pageRef(ValueIds.T_URI, 1)).isZero();
		assertThat(locator.pageRef(ValueIds.T_URI, Long.MAX_VALUE >>> LmdbReferenceNodeLocator.PAGE_SHIFT)).isZero();
		assertThat(locator.headerRef(ValueIds.T_URI, LmdbReferenceNodeLocator.PAGE_SLOTS * 5L + 1)).isZero();
		// a type with a zero bound has no pages at all
		assertThat(locator.headerRef(ValueIds.T_LITERAL, 0)).isZero();
	}

	@Test
	void builderEnforcesOrderAndBounds() {
		long[] tops = { LmdbReferenceNodeLocator.PAGE_SLOTS, LmdbReferenceNodeLocator.PAGE_SLOTS, 0, 0 };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);
		builder.addNode(ValueIds.T_URI, 10, emptyPlanes(), emptyPlanes());

		assertThatIllegalArgumentException()
				.isThrownBy(() -> builder.addNode(ValueIds.T_URI, 10, emptyPlanes(), emptyPlanes()));
		assertThatIllegalArgumentException()
				.isThrownBy(() -> builder.addNode(ValueIds.T_URI, 9, emptyPlanes(), emptyPlanes()));
		assertThatIllegalArgumentException()
				.isThrownBy(() -> builder.addNode(ValueIds.T_URI, LmdbReferenceNodeLocator.PAGE_SLOTS,
						emptyPlanes(), emptyPlanes()));
		assertThatIllegalArgumentException().isThrownBy(() -> {
			long[][] unsorted = emptyPlanes();
			long[][] refs = emptyPlanes();
			unsorted[0] = new long[] { 5, 5 };
			refs[0] = new long[] { 1, 2 };
			builder.addNode(ValueIds.T_LITERAL, 0, unsorted, refs);
		});
	}

	@Test
	void isReferenceCoversReferenceTypesOnly() {
		assertThat(ValueIds.isReference(ValueIds.createId(ValueIds.T_URI, 5))).isTrue();
		assertThat(ValueIds.isReference(ValueIds.createId(ValueIds.T_LITERAL, 5))).isTrue();
		assertThat(ValueIds.isReference(ValueIds.createId(ValueIds.T_BNODE, 5))).isTrue();
		assertThat(ValueIds.isReference(ValueIds.createId(ValueIds.T_TRIPLE, 5))).isTrue();
		assertThat(ValueIds.isReference(ValueIds.createId(ValueIds.T_INTEGER, 5))).isFalse();
		assertThat(ValueIds.isReference(ValueIds.createId(ValueIds.T_SHORTSTRING, 5))).isFalse();
		// an inlined double has the low bit set and is never a reference
		assertThat(ValueIds.isReference(Double.doubleToLongBits(2.0) | 1L)).isFalse();
	}
}
